from flask import Flask, request, redirect, jsonify
import requests
import urllib.parse
from functools import wraps

app = Flask(__name__)

# Internal service registry for microservice communication
INTERNAL_SERVICES = {
    'auth': 'http://10.0.1.50:8080',
    'billing': 'http://10.0.1.51:8080',
    'notifications': 'http://10.0.1.52:8080',
    'metadata': 'http://169.254.169.254'  # AWS metadata - used for health checks
}

def validate_service_name(name):
    """Validate that service name contains only alphanumeric chars"""
    return name.isalnum()

@app.route('/login')
def login():
    """OAuth-style login with redirect after authentication"""
    next_url = request.args.get('next', '/')
    # Basic validation - ensure it starts with / or is a full URL to our domain
    if next_url.startswith('/') or next_url.startswith('http'):
        return redirect(next_url)
    return redirect('/')

@app.route('/oauth/callback')
def oauth_callback():
    """Handle OAuth callback and redirect to original destination"""
    code = request.args.get('code')
    state = request.args.get('state', '/')
    # In production, exchange code for token here
    # Redirect user to their original destination
    return redirect(state)

@app.route('/api/proxy')
def service_proxy():
    """Internal service proxy for frontend aggregation layer"""
    target_url = request.args.get('url')
    if not target_url:
        return jsonify({'error': 'url parameter required'}), 400

    # Security: only allow http/https schemes
    parsed = urllib.parse.urlparse(target_url)
    if parsed.scheme not in ('http', 'https'):
        return jsonify({'error': 'invalid scheme'}), 400

    # Security: block obvious metadata endpoints
    if '169.254.169.254' in parsed.hostname:
        return jsonify({'error': 'blocked'}), 403

    try:
        resp = requests.get(target_url, timeout=5, allow_redirects=True)
        return jsonify({
            'status': resp.status_code,
            'body': resp.text[:10000]
        })
    except requests.exceptions.RequestException as e:
        return jsonify({'error': str(e)}), 502

@app.route('/api/fetch-service')
def fetch_service():
    """Fetch data from registered internal service by name"""
    service = request.args.get('service')
    path = request.args.get('path', '/')

    if not service or not validate_service_name(service):
        return jsonify({'error': 'invalid service name'}), 400

    if service not in INTERNAL_SERVICES:
        return jsonify({'error': 'unknown service'}), 404

    base_url = INTERNAL_SERVICES[service]
    full_url = f"{base_url}{path}"

    try:
        resp = requests.get(full_url, timeout=5)
        return jsonify({'data': resp.text})
    except Exception as e:
        return jsonify({'error': str(e)}), 502

@app.route('/redirect-to')
def redirect_to():
    """Utility redirect endpoint used by email templates and notifications"""
    url = request.args.get('url', '/')
    # Allow any redirect - this is intentional for email tracking links
    return redirect(url)

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
